+func TestInstanceMetadataClientIsAvailable(t *testing.T) {
+	tests := []struct {
+		name      string
+		body      string
+		status    int
+		available bool
+	}{
+		{name: "short instance ID", body: "i-1a2b3c4d", available: true},
+		{name: "long instance ID", body: "i-1234567890abcdef0", available: true},
+		{name: "captive portal", body: "<!DOCTYPE html><html>Login</html>", available: false},
+		{name: "invalid length", body: "i-123456789", available: false},
+		{name: "invalid characters", body: "i-1234567g", available: false},
+		{name: "trailing content", body: "i-1a2b3c4d\n", available: false},
+		{name: "metadata error", status: http.StatusNotFound, available: false},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+				if r.Method == http.MethodPut {
+					w.WriteHeader(http.StatusNotFound) // IMDSv1 fallback
+					return
+				}
+				assert.Equal(t, "/latest/meta-data/instance-id", r.URL.Path)
+				if tt.status != 0 {
+					w.WriteHeader(tt.status)
+				}
+				_, _ = w.Write([]byte(tt.body))
+			}))
+			defer server.Close()
+
+			imdsClient := imds.New(imds.Options{Endpoint: server.URL, HTTPClient: server.Client()})
+			client, err := NewInstanceMetadataClient(context.Background(), WithIMDSClient(imdsClient))
+			require.NoError(t, err)
+			assert.Equal(t, tt.available, client.IsAvailable(context.Background()))
+		})
+	}
+}
+
+func TestInstanceMetadataClientOptions(t *testing.T) {
+	wantErr := errors.New("option failed")
+	client, err := NewInstanceMetadataClient(context.Background(), func(client *InstanceMetadataClient) error {
+		return wantErr
+	})
+	require.Nil(t, client)
+	require.ErrorIs(t, err, wantErr)
+}
+
+func TestInstanceMetadataClientIsAvailableTimeout(t *testing.T) {
+	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		<-r.Context().Done()
+	}))
+	defer server.Close()
+
+	client, err := NewInstanceMetadataClient(context.Background(), WithIMDSClient(imds.New(imds.Options{
+		Endpoint: server.URL, HTTPClient: server.Client(),
+	})))
+	require.NoError(t, err)
+
+	start := time.Now()
+	assert.False(t, client.IsAvailable(context.Background()))
+	assert.Less(t, time.Since(start), time.Second)
+}

